const producido = $('Query Balance Producido').all()
  .map(i => i.json)
  .filter(r => r && r.fecha)
  .map(r => ({
    fecha: r.fecha,
    doctor_id: r.doctor_id || null,
    doctor_name: r.doctor_name,
    patient_name: r.patient_name || '',
    service_name: r.service_name,
    invoice_doc_no: r.invoice_doc_no,
    currency: r.currency,
    importe: Number(r.importe || 0),
  }));

const cobrado = $('Query Balance Cobrado').all()
  .map(i => i.json)
  .filter(r => r && r.fecha)
  .map(r => ({
    fecha: r.fecha,
    doctor_id: r.doctor_id || null,
    doctor_name: r.doctor_name,
    patient_name: r.patient_name || '',
    invoice_doc_no: r.invoice_doc_no || '',
    payment_method: r.payment_method || 'N/D',
    currency: r.currency,
    importe: Number(r.importe || 0),
  }));

const pendiente = $('Query Balance Pendiente').all()
  .map(i => i.json)
  .filter(r => r && r.currency)
  .map(r => ({
    doctor_id: r.doctor_id || null,
    doctor_name: r.doctor_name,
    currency: r.currency,
    total_facturado: Number(r.total_facturado || 0),
    total_cobrado: Number(r.total_cobrado || 0),
    saldo: Number(r.saldo || 0),
  }));

const total_producido = producido.reduce((s, r) => s + r.importe, 0);
const total_cobrado   = cobrado.reduce((s, r) => s + r.importe, 0);
const total_pendiente = pendiente.reduce((s, r) => s + r.saldo, 0);
const num_doctores = new Set(pendiente.map(r => r.doctor_id).filter(Boolean)).size;

return [{ json: {
  summary: { total_producido, total_cobrado, total_pendiente, num_doctores },
  producido,
  cobrado,
  pendiente
} }];
